import * as React from "react";
export const BootstrapThemePresetContext = React.createContext(undefined);
export function useBootstrapThemePreset() {
    const context = React.useContext(BootstrapThemePresetContext);
    if (!context)
        throw new Error("useBootstrapThemePreset must be used within <ThemeProvider />");
    return context;
}
